#!/usr/bin/env python3
"""Generates services/<slug>/index.html from the data below. Run from repo root: python3 _docs/build-services.py
After the first build you can also edit the generated pages by hand; re-running overwrites them."""
import re, os, html
base=open('services/ai-agent-inventory/index.html').read()
HEAD=base.split('<main id="main">')[0]
FOOT='<footer class="site-footer">'+base.split('<footer class="site-footer">')[1]
LD=re.compile(r'<script type="application/ld\+json">.*?</script>',re.S)
def ent(s): return s.replace('&','&amp;') if '&amp;' not in s else s
def a(url,text): return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{text}</a>'

