def render(p):
    h=HEAD
    h=h.replace('AI &amp; Agent Inventories | Flowhaus.ai',p['name']+' | Flowhaus.ai')
    h=h.replace('What an AI and agent inventory is, what goes into building one, and what you have at the end. A focused consulting outcome from Flowhaus.ai.',html.escape(p['desc'],quote=True))
    h=h.replace('ai-agent-inventory',p['slug'])
    h=h.replace('content="AI &amp; Agent Inventories"','content="'+p['name']+'"')
    h=LD.sub('<script type="application/ld+json">\n  {\n    "@context": "https://schema.org",\n    "@type": "Service",\n    "name": "'+p['name'].replace('&amp;','&')+'",\n    "provider": {"@type": "Organization", "name": "Flowhaus.ai", "url": "https://flowhaus.ai/"},\n    "url": "https://flowhaus.ai/services/'+p['slug']+'/"\n  }\n  </script>',h)
    o=[]
    o.append('<main id="main">\n    <article class="article service">\n      <div class="wrap">\n        <a class="back-link" href="/#consulting">&larr; Focused consulting outcomes</a>\n        <header class="service-head">\n          <p class="service-tier"><span>%s</span> %s</p>\n          <h1>%s</h1>\n          <p class="lede">%s</p>\n        </header>\n        <div class="prose">'%(p['tier'],p['tiername'],p['name'],ent(p['lede'])))
    o.append(f'          <h2>{p["why_h"]}</h2>\n          <p>{ent(p["why"])}</p>')
    if p.get('stats'):
        o.append('          <div class="stat-row">\n'+'\n'.join(f'            <div class="stat"><span class="stat-num">{n}</span><span class="stat-label">{l}</span></div>' for n,l in p['stats'])+'\n          </div>')
    if p.get('table'):
        o.append('          <table>\n            <thead><tr><th scope="col">Date</th><th scope="col">What applies</th></tr></thead>\n            <tbody>\n'+'\n'.join(f'              <tr><td>{d}</td><td>{t}</td></tr>' for d,t in p['table'])+'\n            </tbody>\n          </table>')
    o.append(f'          <p class="stat-source">Source: {p["src"]}</p>')
    o.append(f'          <p>{ent(p["after"])}</p>')
    o.append('          <h2>What goes into it</h2>\n          <ol class="steps">\n'+'\n'.join(f'            <li><div><strong>{t}</strong>{ent(d)}</div></li>' for t,d in p['steps'])+'\n          </ol>')
    o.append('          <h2>What you have at the end</h2>\n          <p>These are the kinds of artifacts this work produces. What you receive depends on your size, your risk, and how you already work.</p>\n          <ul class="deliverables">\n'+'\n'.join(f'            <li><strong>{t}</strong><span>{d}</span></li>' for t,d in p['deliv'])+'\n          </ul>')
    o.append('          <!-- OUTCOME FIGURE (add when an example is ready):\n          <figure class="outcome-fig"><img src="/assets/img/services/EXAMPLE.png" alt="DESCRIBE THE IMAGE" width="1200" height="750"><figcaption>Example: caption</figcaption></figure>\n          -->')
    o.append('          <h2>Learn more</h2>\n          <ul class="reading">\n'+'\n'.join(f'            <li><a href="{u}" target="_blank" rel="noopener noreferrer">{t}</a><span>{d}</span></li>' for u,t,d in p['reading'])+'\n          </ul>\n        </div>')
    o.append(f'        <aside class="article-cta">\n          <h2>{p["cta"][0]}</h2>\n          <p>{ent(p["cta"][1])}</p>\n          <a class="btn" href="/#contact">Book a discovery call</a>\n        </aside>\n      </div>\n    </article>\n  </main>\n  ')
    return h+'\n'.join(o)+FOOT
for p in PAGES:
    os.makedirs('services/'+p['slug'],exist_ok=True)
    open('services/'+p['slug']+'/index.html','w').write(render(p))
print([p['slug'] for p in PAGES])
